#include <chrono>
#include <iomanip>
#include <iostream>

#include <noarr/traversers.hpp>

#include "defines.hpp"
#include "deriche.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// img[i][j] with j the innermost (contiguous) dimension, as in C (img[W][H])
	DEFINE_PROTO_STRUCT(img_layout, j_vec ^ i_vec);
} tuning;

// initialization function
// imgIn, imgOut: i x j
void init_array(num_t &alpha, auto imgIn, auto imgOut) {
	using namespace noarr;
	(void)imgOut; // not used, kept for interface similarity

	alpha = SCALAR_VAL(0.25); // parameter of the filter

	// input should be between 0 and 1 (grayscale image pixel)
	traverser(imgIn).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		imgIn[state] = (num_t)(((313 * i + 991 * j) % 65536) / 65535.0f);
	});
}

// computation kernel
// imgIn, imgOut, y1, y2: i x j
//
// Optimizations compared to the original version:
//
// 1. Vertical combine (imgOut = c1 * (y1 + y2)) is fused with the
//    horizontal causal pass (3rd pass). This removes one full 2D pass
//    over the image and avoids re-reading imgOut in that pass.
// 2. Final combine (imgOut = c2 * (y1 + y2)) is fused with the
//    horizontal anti-causal pass (4th pass). This removes another
//    full 2D pass and avoids an extra read of y2 and write to imgOut.
// 3. Inner loops avoid redundant state queries and memory accesses by
//    caching indices and values in scalars.
// 4. Reverse traversals are still driven by forward Noarr traversers,
//    but the mapping to the reversed index is done with simple integer
//    arithmetic, keeping memory accesses contiguous (just reversed).
[[gnu::flatten, gnu::noinline]]
void kernel_deriche(num_t alpha, auto imgIn, auto imgOut, auto y1, auto y2) {
	using namespace noarr;

	num_t k;
	num_t a1, a2, a3, a4, a5, a6, a7, a8;
	num_t b1, b2, c1, c2;

#pragma scop
	// coefficient setup (unchanged from C version)
	k = (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) *
	    (SCALAR_VAL(1.0) - EXP_FUN(-alpha)) /
	    (SCALAR_VAL(1.0) + SCALAR_VAL(2.0) * alpha * EXP_FUN(-alpha) - EXP_FUN(SCALAR_VAL(2.0) * alpha));
	a1 = a5 = k;
	a2 = a6 = k * EXP_FUN(-alpha) * (alpha - SCALAR_VAL(1.0));
	a3 = a7 = k * EXP_FUN(-alpha) * (alpha + SCALAR_VAL(1.0));
	a4 = a8 = -k * EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	b1 = POW_FUN(SCALAR_VAL(2.0), -alpha);
	b2 = -EXP_FUN(SCALAR_VAL(-2.0) * alpha);
	c1 = c2 = SCALAR_VAL(1.0);

	// lengths used for reverse traversals
	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// 1st pass: causal filter along j, for each i (forward j)
	// for (i=0; i<W; i++)
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++)
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2; ...
	traverser(y1, imgIn).template for_dims<'i'>([&](auto row_trav) {
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

		// row_trav iterates j (contiguous) for the fixed i
		row_trav.for_each([&](auto state) {
			const num_t x = imgIn[state];
			const num_t y = a1 * x + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y;
			xm1 = x;
			ym2 = ym1;
			ym1 = y;
		});
	});

	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	// Original C: j from H-1 down to 0
	// Here we traverse j in 0..H-1 and map r -> j = H-1-r
	traverser(y2, imgIn).template for_dims<'i'>([&](auto row_trav) {
		const std::size_t i_idx = get_index<'i'>(row_trav.state());

		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

		row_trav.for_each([&](auto state) {
			const std::size_t r_j   = get_index<'j'>(state);
			const std::size_t j_idx = h_len - 1 - r_j;
			auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

			const num_t x = imgIn[rev_state];
			const num_t y = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

			y2[rev_state] = y;

			xp2 = xp1;
			xp1 = x;
			yp2 = yp1;
			yp1 = y;
		});
	});

	// At this point:
	//   y1 = vertical causal pass
	//   y2 = vertical anti-causal pass
	// Instead of performing an explicit vertical combine pass
	//   imgOut = c1 * (y1 + y2)
	// and then reading imgOut in the 3rd pass, we fuse both:
	//   - compute v = c1 * (y1 + y2)
	//   - store v into imgOut (for the 4th pass)
	//   - immediately use v as input to the horizontal causal filter.

	// 3rd pass: fused vertical combine + causal filter along i, for each j
	// for (j=0; j<H; j++)
	//   tm1=0; ym1=0; ym2=0;
	//   for (i=0; i<W; i++) {
	//     v        = c1 * (y1[i][j] + y2[i][j]);   // vertical combine
	//     imgOut[i][j] = v;                        // same as original combine pass
	//     y1[i][j] = a5*v + a6*tm1 + b1*ym1 + b2*ym2; ...
	//   }
	traverser(y1, y2, imgOut).template for_dims<'j'>([&](auto col_trav) {
		num_t tm1 = SCALAR_VAL(0.0);
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);

		col_trav.for_each([&](auto state) {
			// state has both 'i' and 'j'
			const num_t v  = c1 * (y1[state] + y2[state]); // vertical combine
			imgOut[state]  = v;                            // store for 4th pass

			const num_t y = a5 * v + a6 * tm1 + b1 * ym1 + b2 * ym2;
			y1[state] = y; // overwrite with horizontal causal result

			tm1 = v;
			ym2 = ym1;
			ym1 = y;
		});
	});

	// 4th pass: fused anti-causal filter along i (reverse i) + final combine
	//
	// Original 4th pass:
	//   use imgOut (vertical combined) as input, write y2 (horizontal anti-causal)
	// Final combine:
	//   imgOut[i][j] = c2 * (y1[i][j] + y2[i][j]);
	//
	// We fuse these:
	//   - read v = imgOut[i][j] (vertical combined)
	//   - compute y2 horizontal anti-causal
	//   - immediately produce final output into imgOut
	traverser(y2, y1, imgOut).template for_dims<'j'>([&](auto col_trav) {
		const std::size_t j_idx = get_index<'j'>(col_trav.state());

		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		col_trav.for_each([&](auto state) {
			// r_i runs forward 0..W-1, we map to i = W-1-r_i
			const std::size_t r_i   = get_index<'i'>(state);
			const std::size_t i_idx = w_len - 1 - r_i;
			auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

			// v is the vertical combined value produced in the fused 3rd pass
			const num_t v = imgOut[rev_state];

			const num_t y2_val = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;
			y2[rev_state]      = y2_val;

			// Final combine: overwrite imgOut with the final result
			const num_t out_val = c2 * (y1[rev_state] + y2_val);
			imgOut[rev_state]   = out_val;

			tp2 = tp1;
			tp1 = v;
			yp2 = yp1;
			yp1 = y2_val;
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t w = W;
	std::size_t h = H;

	// parameter
	num_t alpha;

	// lengths shared by all images
	auto set_lengths =
		noarr::set_length<'i'>(w) ^
		noarr::set_length<'j'>(h);

	// images: i x j
	auto imgIn  = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto imgOut = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y1     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);
	auto y2     = noarr::bag(noarr::scalar<num_t>() ^ tuning.img_layout ^ set_lengths);

	// initialize data
	init_array(alpha, imgIn.get_ref(), imgOut.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_deriche(alpha, imgIn.get_ref(), imgOut.get_ref(), y1.get_ref(), y2.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (acts as DCE prevention)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, imgOut.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
