	// We keep the traverser going in forward order over j, but
	// maintain a separate index state that walks j in reverse:
	//   current_rev_state: (i, H-1), (i, H-2), ..., (i, 0)
	//
	// This avoids constructing a fresh reversed state from scratch
	// on every iteration and keeps all loop nests expressed with
	// Noarr traversers.
	// ------------------------------------------------------------------
	traverser(y2, imgIn).template for_dims<'i'>([&](auto inner) {
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

