		auto base_state = inner.state();
		auto rev_state  = base_state.template with<index_in<'j'>>(last_j);

		inner.for_each([&](auto /*fwd_state*/) {
			// Access the reversed element
			const num_t x_cur = imgIn[rev_state];
			const num_t y_cur = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

			y2[rev_state] = y_cur;

			// advance the scalar recurrence
			xp2 = xp1;
			xp1 = x_cur;
			yp2 = yp1;
			yp1 = y_cur;

			// move one step backwards in j
			rev_state = rev_state - idx<'j'>(1);
		});
	});

