	const std::size_t w_len = imgIn | get_length<'i'>();
	const std::size_t h_len = imgIn | get_length<'j'>();

	// ------------------------------------------------------------------
	// 1st pass: causal filter along j, for each i (forward j)
	// for (i=0; i<W; i++)
	//   ym1=0; ym2=0; xm1=0;
	//   for (j=0; j<H; j++)
	//     y1[i][j] = a1*imgIn[i][j] + a2*xm1 + b1*ym1 + b2*ym2; ...
	// ------------------------------------------------------------------
	traverser(y1, imgIn).template for_dims<'i'>([&](auto inner) {
		num_t ym1 = SCALAR_VAL(0.0);
		num_t ym2 = SCALAR_VAL(0.0);
		num_t xm1 = SCALAR_VAL(0.0);

		// Iterate j as the innermost, contiguous dimension
		inner.template for_each<'j'>([&](auto state) {
			const num_t x_cur = imgIn[state];
			const num_t y_cur = a1 * x_cur + a2 * xm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_cur;

			// update recurrence state
			xm1 = x_cur;
			ym2 = ym1;
			ym1 = y_cur;
		});
	});

	// ------------------------------------------------------------------
	// 2nd pass: anti-causal filter along j, for each i (reverse j)
	//
	// Original C: for (j = H-1; j >= 0; --j)
	// Here we still traverse j in 0..H-1 using Noarr, but we keep an
	// explicit descending index j_idx and map it to j = H-1, H-2, ..., 0.
	// This avoids recomputing H-1-r and repeatedly extracting indices
	// from the state, and keeps the anti-causal recurrence identical.
	// ------------------------------------------------------------------
	traverser(y2, imgIn).template for_dims<'i'>([&](auto inner) {
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);
		num_t xp1 = SCALAR_VAL(0.0);
		num_t xp2 = SCALAR_VAL(0.0);

