		const std::size_t i_idx = get_index<'i'>(inner.state());
		std::size_t       j_idx = h_len; // start "one past the end", we pre-decrement

		inner.template for_each<'j'>([&](auto /*state*/) {
			// map forward traversal r = 0..H-1 to reverse j = H-1..0
			--j_idx;
			auto rev_state = idx<'i', 'j'>(i_idx, j_idx);

			const num_t x_cur = imgIn[rev_state];
			const num_t y_cur = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2;

			y2[rev_state] = y_cur;

			// update recurrence state
			xp2 = xp1;
			xp1 = x_cur;
			yp2 = yp1;
			yp1 = y_cur;
		});
	});

	// ------------------------------------------------------------------
	// Combine vertical passes
	// imgOut[i][j] = c1 * (y1[i][j] + y2[i][j]);
	// Traverser iterates i (outer) then j (inner), matching layout.
	// ------------------------------------------------------------------
	traverser(imgOut, y1, y2).for_each([&](auto state) {
		imgOut[state] = c1 * (y1[state] + y2[state]);
	});

	// ------------------------------------------------------------------
	// 3rd pass: causal filter along i, for each j (forward i)
	// for (j=0; j<H; j++)
	//   tm1=0; ym1=0; ym2=0;
	//   for (i=0; i<W; i++)
	//     y1[i][j] = a5*imgOut[i][j] + a6*tm1 + b1*ym1 + b2*ym2; ...
	// ------------------------------------------------------------------
