		// recurrence is per (fixed) j, so we must keep this order.
		inner.template for_each<'i'>([&](auto state) {
			const num_t x_cur = imgOut[state];
			const num_t y_cur = a5 * x_cur + a6 * tm1 + b1 * ym1 + b2 * ym2;

			y1[state] = y_cur;

			// update recurrence state
			tm1 = x_cur;
			ym2 = ym1;
			ym1 = y_cur;
		});
	});

