	// 4th pass: anti-causal filter along i, for each j (reverse i)
	//
	// Original C: for (i = W-1; i >= 0; --i)
	// As in the 2nd pass, we traverse i forward with Noarr but keep an
	// explicit descending index i_idx so that the recurrence follows
	// the exact same sequence as in the C reference.
	// ------------------------------------------------------------------
	traverser(y2, imgOut).template for_dims<'j'>([&](auto inner) {
		num_t tp1 = SCALAR_VAL(0.0);
		num_t tp2 = SCALAR_VAL(0.0);
		num_t yp1 = SCALAR_VAL(0.0);
		num_t yp2 = SCALAR_VAL(0.0);

		// column index is fixed inside this inner traverser; compute once
		const std::size_t j_idx_fixed = get_index<'j'>(inner.state());
		std::size_t       i_idx       = w_len; // start "one past the end"

		inner.template for_each<'i'>([&](auto /*state*/) {
			--i_idx;
			auto rev_state = idx<'i', 'j'>(i_idx, j_idx_fixed);

			const num_t x_cur = imgOut[rev_state];
			const num_t y_cur = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2;

			y2[rev_state] = y_cur;

			// update recurrence state
			tp2 = tp1;
			tp1 = x_cur;
			yp2 = yp1;
			yp1 = y_cur;
		});
	});

